import { app, Menu, nativeImage, nativeTheme, Tray, type NativeImage } from 'electron';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import fallbackIcon from '../../../public/icon/32.png?asset';
import { resolveTrayState, tooltipText, trayIconName, type TrayState } from './tray-model';

/** desktop/resources/tray, generated by `npm run icons`. */
const ICON_DIR = join(import.meta.dirname, '../../resources/tray');
const FLASH_MS = 600;

export interface TrayHandlers {
  onOpen(): void;
  onToggle(): void;
  onSettings(): void;
  onTogglePause(): void;
  onPalette(): void;
  onScreenshot(): void;
  onQuit(): void;
}

export interface TrayStats {
  count: number;
  today: number;
  last?: { label: string; at: number };
}

export function createTray(h: TrayHandlers) {
  let paused = false;
  let attention = false;
  let flashing = false;
  let stats: TrayStats = { count: 0, today: 0 };
  let showCount = false;
  let flashTimer: ReturnType<typeof setTimeout> | undefined;
  let currentState: TrayState = 'idle';
  let currentTooltip = '';

  const darkTaskbar = () => nativeTheme.shouldUseDarkColors;

  function image(state: TrayState): NativeImage {
    const file = join(ICON_DIR, trayIconName(state, process.platform, darkTaskbar()) + '.png');
    return existsSync(file) ? nativeImage.createFromPath(file) : nativeImage.createFromPath(fallbackIcon);
  }

  const tray = new Tray(image('idle'));

  function menu() {
    return Menu.buildFromTemplate([
      { label: 'Open mouStache', click: h.onOpen },
      { label: paused ? 'Resume capture' : 'Pause capture', click: h.onTogglePause },
      { label: 'Quick palette', click: h.onPalette },
      { label: 'Region screenshot', click: h.onScreenshot },
      { label: 'Settings…', click: h.onSettings },
      { type: 'separator' },
      {
        label: 'Launch at login',
        type: 'checkbox',
        checked: app.getLoginItemSettings().openAtLogin,
        click: (item) => app.setLoginItemSettings({ openAtLogin: item.checked, args: ['--hidden'] }),
      },
      { type: 'separator' },
      { label: 'Quit mouStache', click: h.onQuit },
    ]);
  }

  function render() {
    currentState = resolveTrayState({ paused, attention, flashing });
    tray.setImage(image(currentState));
    currentTooltip = tooltipText({ count: stats.count, last: stats.last, paused, now: Date.now() });
    tray.setToolTip(currentTooltip);
    tray.setContextMenu(menu());
    if (process.platform === 'darwin') tray.setTitle(showCount ? String(stats.today) : '');
  }

  tray.on('click', h.onToggle);
  nativeTheme.on('updated', render);
  const minute = setInterval(render, 60_000); // keeps "2 min ago" honest
  render();

  return {
    setStats(s: TrayStats) {
      stats = s;
      render();
    },
    setPaused(p: boolean) {
      if (p !== paused) {
        paused = p;
        render();
      }
    },
    setAttention(a: boolean) {
      if (a !== attention) {
        attention = a;
        render();
      }
    },
    setShowCount(v: boolean) {
      if (v !== showCount) {
        showCount = v;
        render();
      }
    },
    /** The ~600 ms "curl" after a capture. */
    flash() {
      flashing = true;
      render();
      if (flashTimer) clearTimeout(flashTimer);
      flashTimer = setTimeout(() => {
        flashing = false;
        render();
      }, FLASH_MS);
    },
    /** For tests. */
    inspect: () => ({ state: currentState, tooltip: currentTooltip, paused }),
    destroy() {
      clearInterval(minute);
      if (flashTimer) clearTimeout(flashTimer);
      tray.destroy();
    },
  };
}

export type TrayController = ReturnType<typeof createTray>;
